// Fetch Chinese public holiday data for the given years and regenerate
// src/gui/holidays/data.ts.
//
// Usage: npm run holidays:update -- 2025 2026
//
// Data: https://github.com/NateScarlet/holiday-cn (MIT, Copyright (c) 2019
// NateScarlet). Each file is generated from a State Council announcement; the
// announcement URLs are kept in the generated file for auditing.
import fs from "node:fs/promises";

const years = process.argv.slice(2).map(Number);

if (!years.length || years.some((year) => !Number.isInteger(year))) {
  console.error("usage: node scripts/update-cn-holidays.mjs <year> [year...]");
  process.exit(1);
}

const days = new Map();
const sources = new Set();

for (const year of years) {
  const url = `https://raw.githubusercontent.com/NateScarlet/holiday-cn/master/${year}.json`;
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`${year}: HTTP ${response.status} for ${url}`);
  }

  const data = await response.json();

  if (!Array.isArray(data.days) || data.days.length === 0) {
    throw new Error(
      `${year}: no holiday data yet (the file is empty). The State Council ` +
        `schedule for ${year} has probably not been published.`
    );
  }

  if (!Array.isArray(data.papers) || data.papers.length === 0) {
    throw new Error(
      `${year}: no source announcement URL found, refusing to import.`
    );
  }

  for (const paper of data.papers) {
    sources.add(paper);
  }

  for (const day of data.days ?? []) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day.date)) {
      throw new Error(`Invalid date "${day.date}" in ${year}.json`);
    }
    if (typeof day.name !== "string" || !day.name) {
      throw new Error(`Missing name for ${day.date} in ${year}.json`);
    }
    if (typeof day.isOffDay !== "boolean") {
      throw new Error(`Invalid isOffDay for ${day.date} in ${year}.json`);
    }

    const existing = days.get(day.date);
    if (existing && existing.name !== day.name) {
      throw new Error(
        `Conflicting entries for ${day.date}: "${existing.name}" vs "${day.name}"`
      );
    }

    days.set(day.date, day);
  }
}

const sorted = [...days.values()].sort((a, b) => a.date.localeCompare(b.date));

const body = sorted
  .map(
    (day) =>
      `  { name: ${JSON.stringify(day.name)}, date: ${JSON.stringify(
        day.date
      )}, isOffDay: ${day.isOffDay} },`
  )
  .join("\n");

const output = `// AUTO-GENERATED by scripts/update-cn-holidays.mjs — do not edit by hand.
// Data: holiday-cn (MIT, Copyright (c) 2019 NateScarlet)
// Sources: ${[...sources].join(", ")}
import type { CnHolidayDay } from "./types";

export const CN_HOLIDAY_DAYS: CnHolidayDay[] = [
${body}
];
`;

const sortedYears = [...years].sort((a, b) => a - b);
const metaOutput = `// AUTO-GENERATED by scripts/update-cn-holidays.mjs — do not edit by hand.
export const CN_HOLIDAY_YEARS = [${sortedYears.join(", ")}] as const;

export const CN_HOLIDAY_SOURCES = [
${[...sources].map((source) => `  ${JSON.stringify(source)},`).join("\n")}
] as const;
`;

const target = new URL("../src/gui/holidays/data.ts", import.meta.url);
const metaTarget = new URL("../src/gui/holidays/meta.ts", import.meta.url);
await fs.mkdir(new URL(".", target), { recursive: true });
await fs.writeFile(target, output);
await fs.writeFile(metaTarget, metaOutput);

console.log(
  `Wrote ${sorted.length} days (${sortedYears.join(
    ", "
  )}) to src/gui/holidays/data.ts`
);
